{
  "rule_name": "rule_reporting_period_10q",
  "file": "/mnt/data/LSF/rules/financebench/agentic_rule_full_data_gpt54mini/all_docs/q02_what_is_the_reporting_period_covered_by_this_document_eg_fis/rule_reporting_period_10q.py",
  "code": "import re\n\n\ndef rule_reporting_period_10q(doc: dict) -> list[dict]:\n    try:\n        spans = []\n        seen = set()\n\n        patterns = [\n            re.compile(r\"\\bfor the quarterly period ended\\b.*\", re.IGNORECASE),\n            re.compile(r\"\\bquarterly report\\b.*\\bperiod ended\\b.*\", re.IGNORECASE),\n        ]\n\n        for line in doc.get(\"lines\", []):\n            text = (line.get(\"text\") or \"\").strip()\n            if not text:\n                continue\n            if any(p.search(text) for p in patterns):\n                key = (line.get(\"page_no\"), line.get(\"line_no\"), text)\n                if key not in seen:\n                    spans.append(\n                        {\n                            \"text\": text,\n                            \"page_no\": line.get(\"page_no\"),\n                            \"line_no\": line.get(\"line_no\"),\n                        }\n                    )\n                    seen.add(key)\n\n        if not spans:\n            full_text = doc.get(\"text\") or \"\"\n            for pattern in patterns:\n                for match in pattern.finditer(full_text):\n                    text = match.group(0).strip()\n                    key = (\"full_text\", text)\n                    if key not in seen:\n                        spans.append({\"text\": text})\n                        seen.add(key)\n\n        return spans\n    except Exception:\n        return []\n",
